#!/usr/bin/env node
/**
 * Regenerate the engine SDK's TypeScript types from their Rust definitions.
 *
 *   node scripts/sdk-bindings.mjs           # regenerate the committed files
 *   node scripts/sdk-bindings.mjs --check   # fail if they are stale; writes nothing
 *
 * # Why a check and not just a generator
 *
 * Generating types does not prevent drift; it only moves where drift can
 * happen. A generated file nobody regenerates is a hand-written file with a
 * misleading header — and the failure mode it produces is the one this whole
 * boundary exists to end: the engine ignores a field it cannot parse, so a
 * stale type shows up as a display that silently does not appear.
 *
 * So the output is committed (the web app builds without a Rust toolchain)
 * and `--check` generates it afresh and fails on any difference. That is what
 * makes the commitment real rather than aspirational.
 *
 * The same shape as `schema.rs` for diesel: generated, committed, and wrong
 * loudly rather than quietly when it falls behind.
 *
 * # Why both modes export somewhere else first
 *
 * `--check` runs inside `pnpm verify`, which the git hooks run, often while an
 * e2e suite is driving a Vite dev server. Vite watches `apps/web/src`, and a
 * check that regenerated in place rewrote every binding — changed or not — and
 * full-reloaded every page under test. So the check exports into a temporary
 * directory and compares; it never touches `apps/web/src`.
 *
 * The write mode goes through the same temporary export and then writes only
 * the files whose content actually differs, so regenerating with nothing to
 * change is not a reload either.
 */

import { execFileSync } from "node:child_process";
import { fileURLToPath } from "node:url";
import {
  existsSync,
  mkdtempSync,
  readdirSync,
  readFileSync,
  rmSync,
  statSync,
  unlinkSync,
  writeFileSync,
} from "node:fs";
import os from "node:os";
import path from "node:path";
import process from "node:process";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const OUT_DIR = path.join(ROOT, "apps", "web", "src", "engine", "sdk");
const OUT_REL = path.relative(ROOT, OUT_DIR);
const check = process.argv.includes("--check");

// The SDK directory holds hand-written files too — the typed command
// wrappers, their compile-fail fixture — and those must not be read as
// generation drift. They would fail this check with advice ("run
// `pnpm sdk:bindings`") that could never fix them, which is a worse gate
// than none: it trains people to ignore it.
//
// So the marker ts-rs writes into every file it owns is the authority on
// what this check governs. A file without it is somebody's own work.
const GENERATED_MARKER = "generated by [ts-rs]";

/** The `.ts` files directly in `dir`, by name. ts-rs writes no subdirectories. */
function tsFiles(dir) {
  if (!existsSync(dir)) return [];
  return readdirSync(dir).filter(
    (name) => name.endsWith(".ts") && statSync(path.join(dir, name)).isFile(),
  );
}

const exportDir = mkdtempSync(path.join(os.tmpdir(), "thunderforge-sdk-"));

// `process.exit` would skip the `finally` that removes the export, so the
// run returns its exit code instead.
try {
  process.exitCode = run();
} finally {
  rmSync(exportDir, { recursive: true, force: true });
}

function run() {
  // ts-rs emits during a test run, so the export is a `cargo test` filtered to
  // the generated `export_bindings_*` cases.
  //
  // The types say only `#[ts(export)]`; where they land is `TS_RS_EXPORT_DIR`
  // alone. `.cargo/config.toml` points it at `target/ts-rs` so an ordinary
  // `cargo test` writes nowhere that matters, and this sets it to a fresh
  // directory — an environment variable already set wins over `[env]`.
  execFileSync(
    "cargo",
    ["test", "-p", "thunderforge_canvas_core", "export_bindings"],
    {
      cwd: ROOT,
      stdio: "inherit",
      env: { ...process.env, TS_RS_EXPORT_DIR: exportDir },
    },
  );

  const generated = tsFiles(exportDir);
  if (generated.length === 0) {
    // An empty export would read as "every committed binding is orphaned";
    // better to say what actually happened.
    console.error(
      `[sdk] cargo exported no bindings into ${exportDir}; nothing to compare`,
    );
    return 1;
  }

  const changed = []; // generated, and the committed file differs or is missing
  for (const name of generated) {
    const fresh = readFileSync(path.join(exportDir, name), "utf8");
    const target = path.join(OUT_DIR, name);
    const committed = existsSync(target) ? readFileSync(target, "utf8") : null;
    if (committed !== fresh) {
      changed.push({ name, fresh, missing: committed === null });
    }
  }

  // A committed binding whose type no longer exports — renamed, removed — is
  // drift as surely as a changed one, and regenerating in place never deleted
  // it.
  const generatedSet = new Set(generated);
  const orphaned = tsFiles(OUT_DIR).filter(
    (name) =>
      !generatedSet.has(name) &&
      readFileSync(path.join(OUT_DIR, name), "utf8").includes(GENERATED_MARKER),
  );

  if (check) {
    if (changed.length === 0 && orphaned.length === 0) {
      console.log("[sdk] generated types match their Rust source");
      return 0;
    }
    const lines = [
      ...changed.map(
        ({ name, missing }) =>
          `  ${missing ? "missing " : "stale   "} ${path.join(OUT_REL, name)}`,
      ),
      ...orphaned.map((name) => `  orphaned ${path.join(OUT_REL, name)}`),
    ];
    console.error(
      "[sdk] Bindings are stale — the committed TypeScript types do not match their Rust source:\n" +
        lines.join("\n") +
        "\n\nRun `pnpm sdk:bindings` and commit the result.",
    );
    return 1;
  }

  for (const { name, fresh } of changed) {
    writeFileSync(path.join(OUT_DIR, name), fresh);
  }
  for (const name of orphaned) {
    unlinkSync(path.join(OUT_DIR, name));
  }
  console.log(
    changed.length === 0 && orphaned.length === 0
      ? `[sdk] ${OUT_REL} already up to date; nothing written`
      : `[sdk] regenerated into ${OUT_REL}: ${changed.length} written, ${orphaned.length} removed`,
  );
  return 0;
}
